  el.querySelectorAll('.letter').forEach(function(l){ var n=l.nextElementSibling, any=false; while(n&&!n.classList.contains('letter')){ if(n.hasAttribute('data-ap')&&n.style.display!=='none') any=true; n=n.nextElementSibling; } l.style.display=any?'':'none'; });
}
