    '<label class="f" for="jrt">Codice team<input id="jrt" value="'+esc(cfg.team)+'" autocomplete="off" autocapitalize="off" placeholder="Il codice dato da Franco"></label>'+
    '<label class="f" for="jrn">Chi sei<select id="jrn"><option value="">Scegli il tuo nome…</option>'+ROSTER.map(function(m){ return '<option value="'+esc(m[0])+'"'+(cfg.name===m[0]?' selected':'')+'>'+esc(m[0])+(m[1]==='lead'?' (Team leader)':'')+'</option>'; }).join('')+'</select></label>'+
    '<p class="hint">Vedi gli appuntamenti di tutti e modifichi solo i tuoi. Quelli “Personale” restano solo sul tuo telefono.</p>'+
    '<div class="actions"><button class="btn" id="jrc" type="button">Annulla</button><button class="btn primary" id="jrs" type="button">Salva</button></div></div></div>';
